package org.wurmrail;

import com.wurmonline.server.behaviours.Action;
import com.wurmonline.server.behaviours.ActionEntry;
import com.wurmonline.server.creatures.Creature;
import com.wurmonline.server.items.*;
import com.wurmonline.server.questions.Question;
import com.wurmonline.server.skills.SkillList;
import com.wurmonline.shared.constants.ItemMaterials;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import org.gotti.wurmunlimited.modsupport.ItemTemplateBuilder;
import org.gotti.wurmunlimited.modsupport.actions.*;
import org.gotti.wurmunlimited.modsupport.questions.*;

/** Placed producer and replay-safe controls; the controller owns all mutations. */
public final class RailwaySteamWaterPump {
    public static int templateId;private static boolean recipesCreated;
    private RailwaySteamWaterPump(){ }
    public enum Interaction {SHOW,START,STOP}
    public enum ActionType {SAVE,START,STOP,REFRESH}
    public interface Api {View snapshot(Creature actor,long id)throws Exception;void submit(Creature actor,long id,Request request);void interact(Creature actor,long id,Interaction interaction);}
    public static void createTemplate()throws IOException {
        if(templateId!=0)return;
        try {
            int image=ItemTemplateFactory.getInstance().getTemplate(ItemList.wagon).getImageNumber();
            templateId=new ItemTemplateBuilder("wurmrail.steamwaterpump.v1")
                    .name("steam water pump","steam water pumps","An industrial pump collecting nearby natural water into a linked Industrial Water Tank. Configure it with Steam Water Pump controls. Fuel is required while pumping; its natural source supplies boiler water. No startup heat or pressure is simulated.")
                    .size(4).itemTypes(new short[]{ItemTypes.ITEM_TYPE_HOLLOW,ItemTypes.ITEM_TYPE_NOTAKE,ItemTypes.ITEM_TYPE_NAMED,ItemTypes.ITEM_TYPE_METAL,ItemTypes.ITEM_TYPE_DECORATION,ItemTypes.ITEM_TYPE_REPAIRABLE,ItemTypes.ITEM_TYPE_LOCKABLE,ItemTypes.ITEM_TYPE_OWNER_MOVEABLE,ItemTypes.ITEM_TYPE_USES_SPECIFIED_CONTAINER_VOLUME})
                    .imageNumber((short)image).behaviourType((short)1).dimensions(220,210,210)
                    .containerSize(1,1,1).maxItemCount(1).maxItemWeight(1).weightGrams(250000)
                    .material(ItemMaterials.MATERIAL_IRON).modelName("model.wurmrail.steamwaterpump.").difficulty(35).decayTime(Long.MAX_VALUE).build().getTemplateId();
            SteamWaterPumpRegistry.register(templateId);
        }catch(NoSuchTemplateException missing){throw new IOException("The pump requires native wagon metadata",missing);}
    }
    public static void createRecipes(){if(recipesCreated)return;if(templateId==0)throw new IllegalStateException("Create the pump template first.");AdvancedCreationEntry recipe=CreationEntryCreator.createAdvancedEntry(SkillList.SMITHING_BLACKSMITHING,ItemList.plank,ItemList.ironBand,templateId,true,true,0,false,false,CreationCategories.TOOLS);recipe.setFinalMaterial(ItemMaterials.MATERIAL_IRON);recipe.addRequirement(new CreationRequirement(1,ItemList.plank,8,true));recipe.addRequirement(new CreationRequirement(2,ItemList.sheetIron,8,true));recipe.addRequirement(new CreationRequirement(3,ItemList.ironBand,6,true));recipe.addRequirement(new CreationRequirement(4,ItemList.nailsIronLarge,4,true));recipesCreated=true;}
    public static boolean isPump(Item item){return item!=null&&SteamWaterPumpRegistry.isPump(item.getTemplateId());}
    public static final class TankChoice {public final long id;public final String label;public TankChoice(long id,String label){if(id<=0)throw new IllegalArgumentException("Choose a valid tank.");this.id=id;this.label=label==null?"":label;}}
    public static final class SourceChoice {public final int x,y,layer;public final String label;public SourceChoice(int x,int y,int layer,String label){if(x<0||y<0||(layer!=0&&layer!=-1))throw new IllegalArgumentException("Choose a valid source.");this.x=x;this.y=y;this.layer=layer;this.label=label==null?"":label;}}
    public static final class View {
        public final long id,revision,tankId;public final int sourceX,sourceY,sourceLayer;public final String name,status,tankSummary,sourceSummary;public final double rate;public final boolean running,canControl;
        public final List<TankChoice> tanks;public final List<SourceChoice> sources;public final SteamSupplyUi.View supplies;
        public View(long id,long revision,String name,boolean running,long tankId,int sourceX,int sourceY,int sourceLayer,String status,String tankSummary,String sourceSummary,double rate,List<TankChoice> tanks,List<SourceChoice> sources,boolean canControl){this(id,revision,name,running,tankId,sourceX,sourceY,sourceLayer,status,tankSummary,sourceSummary,rate,tanks,sources,canControl,SteamSupplyUi.View.empty(false));}
        public View(long id,long revision,String name,boolean running,long tankId,int sourceX,int sourceY,int sourceLayer,String status,String tankSummary,String sourceSummary,double rate,List<TankChoice> tanks,List<SourceChoice> sources,boolean canControl,SteamSupplyUi.View supplies){if(id<=0||revision< -1||!Double.isFinite(rate)||rate<=0||tanks==null||tanks.size()>512||sources==null||sources.size()>64)throw new IllegalArgumentException("Choose current pump controls.");this.id=id;this.revision=revision;this.name=name==null?"Steam Water Pump":name;this.running=running;this.tankId=tankId;this.sourceX=sourceX;this.sourceY=sourceY;this.sourceLayer=sourceLayer;this.status=status==null?"":status;this.tankSummary=tankSummary==null?"None":tankSummary;this.sourceSummary=sourceSummary==null?"None":sourceSummary;this.rate=rate;this.canControl=canControl;Set<Long> tankIds=new HashSet<Long>();for(TankChoice c:tanks)if(c==null||!tankIds.add(c.id))throw new IllegalArgumentException("Repeated tank choice.");Set<String> sourceIds=new HashSet<String>();for(SourceChoice c:sources)if(c==null||!sourceIds.add(c.x+","+c.y+","+c.layer))throw new IllegalArgumentException("Repeated source choice.");this.tanks=Collections.unmodifiableList(new ArrayList<TankChoice>(tanks));this.sources=Collections.unmodifiableList(new ArrayList<SourceChoice>(sources));if(supplies==null||supplies.waterRequired)throw new IllegalArgumentException("The pump uses natural boiler water and requires fuel controls only.");this.supplies=supplies;}
    }
    public static final class Request {
        public final ActionType action;public final long id,revision,tankId;public final int sourceX,sourceY,sourceLayer;public final SteamSupplyUi.Selection supplies;
        private Request(View v,ActionType action,long tank,int x,int y,int layer){this(v,action,tank,x,y,layer,SteamSupplyUi.unchanged(v.supplies));}
        private Request(View v,ActionType action,long tank,int x,int y,int layer,SteamSupplyUi.Selection supplies){this.action=action;id=v.id;revision=v.revision;tankId=tank;sourceX=x;sourceY=y;sourceLayer=layer;this.supplies=supplies;}
        public static Request refresh(View v){return new Request(v,ActionType.REFRESH,v.tankId,v.sourceX,v.sourceY,v.sourceLayer);}
    }
    public static void show(final Creature actor,final long id,final Api api)throws Exception {final View view=api.snapshot(actor,id);if(view.id!=id)throw new IllegalArgumentException("The pump changed. Refresh its controls.");final AtomicBoolean answered=new AtomicBoolean();ModQuestions.createQuestion(actor,"Steam Water Pump","",id,new ModQuestion(){@Override public void sendQuestion(Question q){sendBml(q,730,670,true,true,ModQuestions.getBmlHeaderNoQuestion(q)+content(view)+"}};null;null;}");}@Override public void answer(Question q,Properties p){if(q.getResponder()!=actor||!answered.compareAndSet(false,true))return;try{Request r=fromAnswers(view,p);if(r!=null)api.submit(actor,id,r);}catch(IllegalArgumentException invalid){actor.getCommunicator().sendNormalServerMessage("[Rail] "+invalid.getMessage());api.submit(actor,id,Request.refresh(view));}}}).sendQuestion();}
    public static String content(View v){StringBuilder b=new StringBuilder();label(b,v.name,true);label(b,"Power: "+(v.running?"AUTOMATIC":"STOPPED"),false);label(b,"Status: "+v.status,false);label(b,"Linked tank: "+v.tankSummary,false);label(b,"Natural source: "+v.sourceSummary,false);label(b,String.format(Locale.ROOT,"Pumping rate: %,.3f litres per second.",v.rate),false);label(b,"Full or unavailable tanks pause pumping. An enabled pump resumes when storage becomes available.",false);b.append(SteamSupplyUi.content(v.supplies,v.canControl));if(v.canControl){int tank=0;for(int i=0;i<v.tanks.size();i++)if(v.tanks.get(i).id==v.tankId)tank=i+1;b.append("harray{label{text='Industrial Water Tank:'};dropdown{id='tank_choice';default='").append(tank).append("';options='No linked tank");for(TankChoice c:v.tanks)b.append(',').append(RailwayBml.option(c.label));b.append("'};};");int source=0;for(int i=0;i<v.sources.size();i++){SourceChoice c=v.sources.get(i);if(c.x==v.sourceX&&c.y==v.sourceY&&c.layer==v.sourceLayer)source=i+1;}b.append("harray{label{text='Natural water:'};dropdown{id='source_choice';default='").append(source).append("';options='No selected source");for(SourceChoice c:v.sources)b.append(',').append(RailwayBml.option(c.label));b.append("'};};");if(v.tanks.isEmpty())label(b,"Place an owned, unlocked Industrial Water Tank within sixteen metres, then refresh.",false);if(v.sources.isEmpty())label(b,"No native water source is available within eight metres on this level.",false);b.append("harray{");button(b,"save","Save settings");button(b,"start","Start pumping");button(b,"stop","Stop pumping");b.append("};");}label(b,"Fuel consumption follows litres actually pumped. No separate boiler-water tank, startup heat, pressure or maintenance is required.",false);b.append("harray{");button(b,"refresh","Refresh status");button(b,"close","Close");b.append("};");return b.toString();}
    public static Request fromAnswers(View v,Properties p){if(v==null||p==null)throw new IllegalArgumentException("Pump answers are missing.");String action=null;for(String k:new String[]{"save","start","stop","refresh","close"})if("true".equals(p.getProperty(k))){if(action!=null)throw new IllegalArgumentException("Choose one pump action.");action=k;}if(action==null||action.equals("close"))return null;if(action.equals("refresh"))return Request.refresh(v);if(!v.canControl)throw new IllegalArgumentException("Only the pump's owner or a GM may change it.");if(action.equals("stop"))return new Request(v,ActionType.STOP,v.tankId,v.sourceX,v.sourceY,v.sourceLayer);int tank=index(p,"tank_choice",v.tanks.size()+1),source=index(p,"source_choice",v.sources.size()+1);SourceChoice c=source==0?null:v.sources.get(source-1);return new Request(v,action.equals("start")?ActionType.START:ActionType.SAVE,tank==0?0:v.tanks.get(tank-1).id,c==null?-1:c.x,c==null?-1:c.y,c==null?0:c.layer,SteamSupplyUi.fromAnswers(v.supplies,p));}
    private static int index(Properties p,String key,int count){try{int i=Integer.parseInt(p.getProperty(key,"").trim());if(i>=0&&i<count)return i;}catch(NumberFormatException bad){ }throw new IllegalArgumentException("Choose valid pump settings.");}
    private static void label(StringBuilder b,String text,boolean bold){b.append("label{");if(bold)b.append("type='bold';");b.append("text='").append(RailwayBml.text(text)).append("'};");}
    private static void button(StringBuilder b,String id,String text){b.append("button{id='").append(id).append("';text='").append(RailwayBml.text(text)).append("'};");}
    public static void registerActions(final Api api){final String[] names={"Steam Water Pump controls","Start pumping","Stop pumping"};final Interaction[] modes={Interaction.SHOW,Interaction.START,Interaction.STOP};final List<ActionEntry> entries=new ArrayList<ActionEntry>();for(String name:names){ActionEntry e=ActionEntry.createEntry((short)ModActions.getNextActionId(),name,"pumping water",new int[]{0});ModActions.registerAction(e);entries.add(e);}for(int i=0;i<entries.size();i++){final ActionEntry entry=entries.get(i);final Interaction mode=modes[i];ModActions.registerAction(new ModAction(){private boolean accepts(Creature p,Item item){return p!=null&&isPump(item)&&MachineStorageLinks.placed(item)&&p.isOnSurface()==item.isOnSurface()&&p.getFloorLevel()==0&&p.getBridgeId()==-10L&&Math.hypot(p.getPosX()-item.getPosX(),p.getPosY()-item.getPosY())<=8;}public BehaviourProvider getBehaviourProvider(){return new BehaviourProvider(){public List<ActionEntry> getBehavioursFor(Creature p,Item item){return entry==entries.get(0)&&accepts(p,item)?Collections.unmodifiableList(entries):null;}public List<ActionEntry> getBehavioursFor(Creature p,Item active,Item item){return getBehavioursFor(p,item);}};}public ActionPerformer getActionPerformer(){return new ActionPerformer(){public short getActionId(){return entry.getNumber();}public boolean action(Action a,Creature p,Item item,short id,float counter){if(id==entry.getNumber()&&accepts(p,item))api.interact(p,item.getWurmId(),mode);return true;}public boolean action(Action a,Creature p,Item active,Item item,short id,float counter){return action(a,p,item,id,counter);}};}});}}
}
